require_once __DIR__.'/../config/config.php';require_role(['teacher','admin']);$u=current_user();$lesson_id=(int)($_GET['lesson_id']??0);$s=db()->prepare("SELECT l.*,c.teacher_id FROM lessons l JOIN courses c ON c.id=l.course_id WHERE l.id=? AND (c.teacher_id=? OR ?)");$s->execute([$lesson_id,$u['id'],$u['role']==='admin'?1:0]);$lesson=$s->fetch();if(!$lesson)exit('Lesson not found or access denied.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=trim($_POST['question']??'');$opts=[trim($_POST['a']??''),trim($_POST['b']??''),trim($_POST['c']??''),trim($_POST['d']??'')];$correct=$_POST['correct_option']??'';if($q&& !in_array('', $opts,true) && in_array($correct,['a','b','c','d'],true)){$s=db()->prepare("INSERT INTO quizzes(lesson_id,question,option_a,option_b,option_c,option_d,correct_option,explanation) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$lesson_id,$q,...$opts,$correct,trim($_POST['explanation']??'')]);flash('Quiz question added.');}else flash('Complete all question and option fields.','error');redirect('/teacher/quiz-edit.php?lesson_id='.$lesson_id);}
$page_title='Quiz builder — LinguaFree';include __DIR__.'/../includes/header.php'; ?>
